import { EXPERIMENT_FIELDS, ITEM_ERROR_FIELDS, ITEM_ERROR_LENGTH, ITEM_ERROR_LINES, ITEM_ID_FIELDS, SUMMARY_ERROR_ITEMS, } from "./constants.js";
import { isInteger, isObject, isString, pythonJson, words, } from "./runtime.js";
function present(value) {
    return value !== null && value !== undefined;
}
function itemErrored(item) {
    return (isObject(item) && ITEM_ERROR_FIELDS.some((field) => present(item[field])));
}
function carriedOver(item) {
    return (isObject(item) && (item.carriedOver === true || item.carried_over === true));
}
function pythonText(value) {
    if (value === true) {
        return "True";
    }
    if (value === false) {
        return "False";
    }
    if (isString(value)) {
        return value;
    }
    return pythonJson(value);
}
function itemErrors(items) {
    const errors = [];
    for (const item of items) {
        if (!itemErrored(item)) {
            continue;
        }
        let error = item[ITEM_ERROR_FIELDS.find((field) => present(item[field]))];
        if (isObject(error)) {
            error = error.message || pythonJson(error);
        }
        const field = ITEM_ID_FIELDS.find((name) => isString(item[name]));
        const trace = field === undefined ? "unknown trace" : item[field];
        let text = words(pythonText(error)).join(" ");
        if (text.length > ITEM_ERROR_LENGTH) {
            text = `${text.slice(0, ITEM_ERROR_LENGTH)}...`;
        }
        const errored = { originalTraceId: trace, error: text };
        if (isInteger(item.attempt)) {
            errored.attempt = item.attempt;
        }
        errors.push(errored);
    }
    return errors;
}
function itemField(item, camel, snake) {
    return camel in item ? item[camel] : item[snake];
}
function canonical(value) {
    return JSON.stringify(value ?? null);
}
export function experimentFields(parsed) {
    const fields = {};
    for (const [name, spellings] of Object.entries(EXPERIMENT_FIELDS)) {
        const key = spellings.find((spelling) => present(parsed[spelling]));
        if (key !== undefined) {
            fields[name] = parsed[key];
        }
    }
    return fields;
}
export function replaySummary(parsed) {
    const items = parsed.items.filter(isObject);
    const replayed = items.filter((item) => !carriedOver(item));
    const errors = itemErrors(replayed);
    const counts = {
        replayed: replayed.length,
        carriedOver: items.length - replayed.length,
        same: 0,
        changed: 0,
        matchedExpected: 0,
        missedExpected: 0,
        errored: errors.length,
    };
    for (const item of replayed) {
        if (itemErrored(item)) {
            continue;
        }
        const equal = canonical(item.result) ===
            canonical(itemField(item, "originalOutput", "original_output"));
        if (itemField(item, "ingestionType", "ingestion_type") === "seeded") {
            counts[equal ? "matchedExpected" : "missedExpected"] += 1;
        }
        else {
            counts[equal ? "same" : "changed"] += 1;
        }
    }
    const summary = {
        cloudSummary: true,
        ...experimentFields(parsed),
        counts,
        erroredItems: errors.slice(0, SUMMARY_ERROR_ITEMS),
    };
    if (errors.length > SUMMARY_ERROR_ITEMS) {
        summary.erroredItemsOmitted = errors.length - SUMMARY_ERROR_ITEMS;
    }
    return summary;
}
export function trailingJson(text) {
    const offsets = [0];
    for (let index = 0; index < text.length; index += 1) {
        if (text[index] === "\n") {
            offsets.push(index + 1);
        }
    }
    for (const offset of offsets) {
        if (text[offset] !== "{") {
            continue;
        }
        let value;
        try {
            value = JSON.parse(text.slice(offset));
        }
        catch {
            continue;
        }
        if (isObject(value)) {
            return [offset, value];
        }
    }
    return [null, null];
}
export function lastJson(text) {
    return trailingJson(text)[1];
}
function resultSummary(stdout) {
    const parsed = lastJson(stdout) ?? {};
    if (parsed.cloudSummary === true) {
        return parsed;
    }
    if (Array.isArray(parsed.items)) {
        return replaySummary(parsed);
    }
    return null;
}
export function summaryMarkdown(result) {
    const summary = resultSummary(result.stdout) ?? {};
    const counts = summary.counts ?? {};
    const testRun = result.testRunId || summary.testRunId;
    const errors = summary.erroredItems ?? [];
    const lines = [
        `Commit: \`${result.commitSha}\``,
        `Exit code: ${result.exitCode}`,
    ];
    if (testRun) {
        lines.unshift(`Test run: \`${testRun}\``);
    }
    if (result.stoppedEarly) {
        lines.push(`Stopped early: ${result.stoppedEarly}`);
    }
    else if (counts.replayed || counts.carriedOver) {
        lines.push(`Replayed: ${counts.replayed}, same: ${counts.same}, changed: ${counts.changed}, errored: ${counts.errored}`);
    }
    let text = `### Bitfab replay\n\n${lines.join("\n\n")}\n`;
    if (errors.length > 0) {
        const shown = errors
            .slice(0, ITEM_ERROR_LINES)
            .map((error) => `trace ${error.originalTraceId}: ${error.error}`);
        if ((counts.errored ?? 0) > shown.length) {
            shown.push(`and ${counts.errored - shown.length} more errored items`);
        }
        text += `\n#### Errored items\n\n${shown
            .map((line) => `- \`${line.replaceAll("`", "'")}\`\n`)
            .join("")}`;
    }
    return text;
}
